package com.icbc.changzhou.ipam;

import com.google.gson.JsonObject;
import java.nio.file.*;
import java.sql.*;
import java.util.*;

/** Regression gate for the confirmed six-network baseline, including an actual V001-to-V010 runtime upgrade. */
public final class StageFourBaselineSmokeTest {
  public static void main(String[] args)throws Exception{
    Path work=Files.createTempDirectory("ipam-stage4-"),db=work.resolve("baseline.db");
    Class<?> type=Class.forName("com.icbc.changzhou.ipam.IpamApplication$Database");java.lang.reflect.Constructor<?> ctor=type.getDeclaredConstructor(Path.class);ctor.setAccessible(true);Object runtime=ctor.newInstance(db);java.lang.reflect.Method migrate=type.getDeclaredMethod("migrate");migrate.setAccessible(true);migrate.invoke(runtime);
    try(Connection c=open(db)){c.createStatement().execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password,is_initial_admin) VALUES('admin','x','管理员','ADMIN',1,0,1)");c.createStatement().execute("INSERT INTO sys_user(username,password_hash,real_name,role,is_active,must_change_password,is_initial_admin) VALUES('tech','x','科技管理员','TECH_ADMIN',1,0,0)");c.createStatement().execute("INSERT INTO branch(code,name,is_active) VALUES('B1','测试支行',1)");c.createStatement().execute("INSERT INTO outlet(branch_id,code,name,is_active) VALUES(1,'O1','测试网点',1)");}
    PhaseFourService service=new PhaseFourService(db);JsonObject plan=new JsonObject();plan.addProperty("branchId",1);plan.addProperty("outletId",1);plan.addProperty("productionCidr","108.56.0.0/24");Map<String,Object> preview=service.previewPlan(plan);if(((List<?>)preview.get("segments")).size()!=6)throw new AssertionError("six-network preview missing segments");service.createPlan(plan,1L);
    try(Connection c=open(db)){assertCount(c,"SELECT count(*) FROM ip_range WHERE outlet_id=1 AND range_type IS NOT NULL",6);assertCount(c,"SELECT count(*) FROM ip_address_pool",1524);assertCount(c,"SELECT count(*) FROM ip_address_pool p JOIN ip_range r ON r.id=p.ip_range_id WHERE p.ip_address=r.gateway",6);assertCount(c,"SELECT count(*) FROM schema_history WHERE version='010'",1);}if(new PhaseTwoService(db).ranges().stream().filter(x->x.get("rangeType")!=null).count()!=6)throw new AssertionError("six-network list must expose rangeType");
    List<Map<String,Object>> nonTech=service.categories("NON_TECH");long sub=0;for(Map<String,Object>x:nonTech)if(x.get("subcategoryId")!=null){sub=((Number)x.get("subcategoryId")).longValue();break;}if(sub==0)throw new AssertionError("non-tech dictionary missing");JsonObject app=new JsonObject();app.addProperty("branchId",1);app.addProperty("outletId",1);app.addProperty("subcategoryId",sub);boolean missingMap=false;try{service.submitApplication(2L,app);}catch(PhaseTwoService.Problem e){missingMap="ASSET_MAPPING_REQUIRED".equals(e.code);}if(!missingMap)throw new AssertionError("unmapped category must block submission");JsonObject mapping=new JsonObject();mapping.addProperty("subcategoryId",sub);mapping.addProperty("rangeType","MONITORING");mapping.addProperty("changeReason","baseline test mapping");service.saveMapping(mapping,1L);long appId=service.submitApplication(2L,app);Map<String,Object> candidates=service.candidates(appId,null,"",1);if(!"MONITORING".equals(candidates.get("rangeType"))||((List<?>)candidates.get("items")).isEmpty())throw new AssertionError("recommended segment candidates missing");long pool=((Number)((Map<?,?>)((List<?>)candidates.get("items")).get(0)).get("id")).longValue();boolean overrideReason=false;try{service.approve(appId,pool,"OFFICE",null,null,1L);}catch(PhaseTwoService.Problem e){overrideReason="RANGE_OVERRIDE_REASON_REQUIRED".equals(e.code);}if(!overrideReason)throw new AssertionError("cross-segment approval must require a reason");service.approve(appId,pool,"MONITORING",null,"测试审批",1L);Map<String,Object> page=service.pool(null,null,"MONITORING","",1);if(((Number)page.get("total")).longValue()<254)throw new AssertionError("new pool query missing type filter");System.out.println("PASS|STAGE4_V010_SIX_NETWORK_RULE_MAPPING_APPLICATION_APPROVAL|"+work);
  }
  private static Connection open(Path db)throws Exception{Connection c=DriverManager.getConnection("jdbc:sqlite:"+db);try(Statement s=c.createStatement()){s.execute("PRAGMA foreign_keys=ON");}return c;}
  private static void assertCount(Connection c,String sql,long expected)throws Exception{try(ResultSet r=c.createStatement().executeQuery(sql)){r.next();if(r.getLong(1)!=expected)throw new AssertionError(sql+" expected="+expected+" actual="+r.getLong(1));}}
}
